import { describe, it, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import UserStats from './UserStats';
import React from 'react';

describe('UserStats', () => {
  it('displays correct statistics for a mixed group of users', () => {
    const users = [
      { id: 1, name: 'User 1', isActive: true },
      { id: 2, name: 'User 2', isActive: false },
      { id: 3, name: 'User 3', isActive: true },
      { id: 4, name: 'User 4', isActive: false },
    ];

    render(<UserStats users={users} />);

    expect(screen.getByText('Active Users: 2')).toBeDefined();
    expect(screen.getByText('Inactive Users: 2')).toBeDefined();
    expect(screen.getByText('Active Percentage: 50.0%')).toBeDefined();
  });

  it('displays correct statistics for all active users', () => {
    const users = [
      { id: 1, name: 'User 1', isActive: true },
      { id: 2, name: 'User 2', isActive: true },
    ];

    render(<UserStats users={users} />);

    expect(screen.getByText('Active Users: 2')).toBeDefined();
    expect(screen.getByText('Inactive Users: 0')).toBeDefined();
    expect(screen.getByText('Active Percentage: 100.0%')).toBeDefined();
  });

  it('displays correct statistics for no active users', () => {
    const users = [
      { id: 1, name: 'User 1', isActive: false },
      { id: 2, name: 'User 2', isActive: false },
    ];

    render(<UserStats users={users} />);

    expect(screen.getByText('Active Users: 0')).toBeDefined();
    expect(screen.getByText('Inactive Users: 2')).toBeDefined();
    expect(screen.getByText('Active Percentage: 0.0%')).toBeDefined();
  });

  it('handles empty user list', () => {
    render(<UserStats users={[]} />);

    expect(screen.getByText('Active Users: 0')).toBeDefined();
    expect(screen.getByText('Inactive Users: 0')).toBeDefined();
    expect(screen.getByText('Active Percentage: 0.0%')).toBeDefined();
  });
});

